#!/bin/bash

# Socket.io Vercel Fix Verification Script
# This script verifies that the Socket.io polling transport is properly configured

echo \"═══════════════════════════════════════════════════════════════\"
echo \"  Socket.io Vercel Fix - Verification Script\"
echo \"═══════════════════════════════════════════════════════════════\"
echo \"\"

# Color codes
RED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color

ISSUES=0
CHECKS=0

# Function to print check result
check_result() {\n  local result=$1\n  local message=$2\n  CHECKS=$((CHECKS + 1))\n  if [ $result -eq 0 ]; then\n    echo -e \"${GREEN}✅${NC} $message\"\n  else\n    echo -e \"${RED}❌${NC} $message\"\n    ISSUES=$((ISSUES + 1))\n  fi\n}\n\necho \"Checking server configuration...\"\necho \"\"\n\n# Check 1: File exists\nif [ -f \"backend/server.js\" ]; then\n  check_result 0 \"backend/server.js exists\"\nelse\n  check_result 1 \"backend/server.js not found\"\nfi\n\necho \"\"\necho \"Checking Socket.io configuration...\"\necho \"\"\n\n# Check 2: transports configured\nif grep -q \"transports: \\[.polling.\\]\" backend/server.js; then\n  check_result 0 \"transports: ['polling'] configured\"\nelse\n  check_result 1 \"transports not set to polling\"\nfi\n\n# Check 3: allowUpgrades disabled\nif grep -q \"allowUpgrades: false\" backend/server.js; then\n  check_result 0 \"allowUpgrades: false is set\"\nelse\n  check_result 1 \"allowUpgrades: false not found\"\nfi\n\n# Check 4: pollInterval configured\nif grep -q \"pollInterval:\" backend/server.js; then\n  check_result 0 \"pollInterval configured\"\nelse\n  check_result 1 \"pollInterval not configured\"\nfi\n\n# Check 5: CORS configured\nif grep -q \"cors: {\" backend/server.js; then\n  check_result 0 \"CORS configuration present\"\nelse\n  check_result 1 \"CORS configuration missing\"\nfi\n\necho \"\"\necho \"Checking client configuration...\"\necho \"\"\n\n# Check 6: Flutter client config - incoming_orders_screen\nif grep -q \"'transports': \\['polling'\\]\" \"lib/screens/incoming_orders_screen.dart\"; then\n  check_result 0 \"incoming_orders_screen.dart uses polling transport\"\nelse\n  check_result 1 \"incoming_orders_screen.dart not configured correctly\"\nfi\n\n# Check 7: Flutter client config - order_notification_service\nif grep -q \"'transports': \\['polling'\\]\" \"lib/services/order_notification_service.dart\"; then\n  check_result 0 \"order_notification_service.dart uses polling transport\"\nelse\n  check_result 1 \"order_notification_service.dart not configured correctly\"\nfi\n\n# Check 8: upgrade disabled in client\nif grep -q \"'upgrade': false\" \"lib/services/order_notification_service.dart\"; then\n  check_result 0 \"Client has 'upgrade: false' set\"\nelse\n  check_result 1 \"Client 'upgrade: false' not found\"\nfi\n\necho \"\"\necho \"Checking error handling...\"\necho \"\"\n\n# Check 9: Error handlers in server\nif grep -q \"onConnect_error\" \"lib/screens/incoming_orders_screen.dart\"; then\n  check_result 0 \"Connection error handlers present\"\nelse\n  check_result 1 \"Connection error handlers not found\"\nfi\n\n# Check 10: Socket.io console logging\nif grep -q \"Socket.io client connected\" backend/server.js; then\n  check_result 0 \"Socket connection logging enabled\"\nelse\n  check_result 1 \"Socket connection logging not found\"\nfi\n\necho \"\"\necho \"═══════════════════════════════════════════════════════════════\"\necho \"Verification Results:\"\necho \"═══════════════════════════════════════════════════════════════\"\necho \"\"\n\nif [ $ISSUES -eq 0 ]; then\n  echo -e \"${GREEN}✅ All checks passed! Socket.io fix is properly configured.${NC}\"\n  echo \"\"\n  echo \"Next steps:\"\n  echo \"  1. npm install (if not done)\"\n  echo \"  2. node server.js (start backend)\"\n  echo \"  3. Test socket connection from browser console\"\n  echo \"  4. Create test order and verify notification\"\nelse\n  echo -e \"${RED}❌ $ISSUES issue(s) found out of $CHECKS checks${NC}\"\n  echo \"\"\n  echo \"Please review the failed checks above and fix the configuration.\"\n  echo \"See SOCKET_IO_VERCEL_FIX.md for detailed instructions.\"\nfi\n\necho \"\"\necho \"═══════════════════════════════════════════════════════════════\"\n\nexit $ISSUES\n"